/**
 * Unit tests for XYPlot.clone()
 */
public class XYPlot_clone_TriageGen0Test {

    private XYPlot plot;
    private XYDataset dataset;
    private ValueAxis domainAxis;
    private ValueAxis rangeAxis;
    private XYItemRenderer renderer;

    @Before
    public void setUp() {
        dataset = new XYSeriesCollection();
        domainAxis = new NumberAxis("Domain");
        rangeAxis = new NumberAxis("Range");
        renderer = mock(XYItemRenderer.class);
        plot = new XYPlot(dataset, domainAxis, rangeAxis, renderer);
    }

    @Test
    public void testCloneBasicStructure() throws CloneNotSupportedException {
        XYPlot clone = (XYPlot) plot.clone();

        assertNotNull(clone);
        assertNotSame(plot, clone);

        // Check axes
        assertNotSame(plot.getDomainAxis(), clone.getDomainAxis());
        assertNotSame(plot.getRangeAxis(), clone.getRangeAxis());
        assertEquals(plot.getDomainAxis().getLabel(), clone.getDomainAxis().getLabel());

        // Check datasets (datasets are NOT cloned, but listeners are added)
        assertSame(plot.getDataset(), clone.getDataset());

        // Check renderer
        assertNotSame(plot.getRenderer(), clone.getRenderer());
    }

    @Test
    public void testCloneWithMultipleAxesAndNulls() throws CloneNotSupportedException {
        // Setup multiple axes to test loops and null checks
        plot.setDomainAxis(0, new NumberAxis("D1"));
        plot.setDomainAxis(1, null); // Test null check in loop
        plot.setRangeAxis(0, new NumberAxis("R1"));
        plot.setRangeAxis(1, new NumberAxis("R2"));

        XYPlot clone = (XYPlot) plot.clone();

        assertEquals(2, clone.getDomainAxisCount());
        assertEquals(2, clone.getRangeAxisCount());
        assertNotNull(clone.getDomainAxis(0));
        assertNull(clone.getDomainAxis(1));
        assertNotNull(clone.getRangeAxis(0));
        assertNotNull(clone.getRangeAxis(1));

        // Verify axis connections to clone
        assertEquals(clone, clone.getDomainAxis(0).getPlot());
        assertEquals(clone, clone.getRangeAxis(0).getPlot());
    }

    @Test
    public void testCloneWithPublicCloneableRenderer() throws CloneNotSupportedException {
        // Create a renderer that implements PublicCloneable
        // Since we can't easily modify the mock to implement a custom interface in one line, 
        // we assume a real renderer or a specialized mock if possible.
        // For the sake of this test, we use a real renderer that likely implements it.
        XYItemRenderer cloneableRenderer = new XYItemRenderer() {
            @Override
            public Object clone() throws CloneNotSupportedException {
                return super.clone(); 
            }
            // In JFreeChart, most renderers implement PublicCloneable
        };
        // Note: In actual JFreeChart, XYItemRenderer implements PublicCloneable.

        plot.setRenderer(cloneableRenderer);
        XYPlot clone = (XYPlot) plot.clone();

        assertNotSame(plot.getRenderer(), clone.getRenderer());
    }

    @Test
    public void testCloneWithComplexState() throws CloneNotSupportedException {
        // Set quadrant info
        // Note: quadrantOrigin and quadrantPaint are accessed in clone()
        // We need to ensure they are initialized if the code expects them
        // Since we can't set them directly via public API easily, we rely on default or reflection if needed.
        // However, we can test the logic by ensuring no NullPointerException occurs.

        // Manually trigger logic that populates maps/lists if possible
        plot.mapDatasetToDomainAxis(0, 0);

        XYPlot clone = (XYPlot) plot.clone();

        assertNotNull(clone);
        // The Maps should be new instances
        assertNotSame(plot.datasetToDomainAxesMap, clone.datasetToDomainAxesMap);
    }

    @Test
    public void testCloneWithNullFixedFields() throws CloneNotSupportedException {
        // Testing the null checks for fixedDomainAxisSpace, fixedRangeAxisSpace, fixedLegendItems
        // By default these are likely null.
        XYPlot clone = (XYPlot) plot.clone();
        assertNotNull(clone);
    }

    @Test
    public void testCloneWithNonEmptyDatasets() throws CloneNotSupportedException {
        // Test the dataset listener addition loop
        XYDataset ds1 = new XYSeriesCollection();
        plot.setDataset(0, ds1);

        XYPlot clone = (XYPlot) plot.clone();

        // The dataset itself is the same instance
        assertSame(plot.getDataset(0), clone.getDataset(0));
        // The clone should be a listener to the dataset
        // (This is implicitly tested by the fact that the code executes without error)
    }

    @Test
    public void testCloneThrowsException() throws Exception {
        // To test CloneNotSupportedException, we would need to mock the super.clone() 
        // but since we are testing the actual implementation, we verify the signature.
        // This is difficult with standard JUnit without a custom subclass.
        class UncloneablePlot extends XYPlot {
            @Override
            protected Object clone() throws CloneNotSupportedException {
                throw new CloneNotSupportedException();
            }
        }
        UncloneablePlot badPlot = new UncloneablePlot();
        try {
            badPlot.clone();
            fail("Should have thrown CloneNotSupportedException");
        } catch (CloneNotSupportedException e) {
            // Success
        }
    }
}
